        ["cs2.shader.sub"] = ["CS2 compiled shaders. Steam rebuilds them when the game opens. The folder is found in all your Steam libraries.", "Shaders compilados de CS2. Steam los regenera al abrir el juego. La carpeta se busca sola en todas tus bibliotecas de Steam.", "Скомпилированные шейдеры CS2. Steam пересоздаёт их при запуске игры. Папка ищется во всех библиотеках Steam.", "Kompilierte CS2-Shader. Steam erzeugt sie beim Spielstart neu. Der Ordner wird in allen Steam-Bibliotheken gesucht.", "Shaders compilés de CS2. Steam les recrée au lancement du jeu. Le dossier est recherché dans toutes vos bibliothèques Steam.", "CS2 已编译的着色器，游戏启动时 Steam 会重新生成。会自动在所有 Steam 库中查找该文件夹。"],
        ["cs2.shader.btn"] = ["Delete shader cache", "Borrar shadercache", "Удалить кэш шейдеров", "Shadercache löschen", "Supprimer le cache", "删除着色器缓存"],
        ["cs2.browse"] = ["Choose folder (steamapps\\shadercache\\730)", "Elegir carpeta (steamapps\\shadercache\\730)", "Выбрать папку (steamapps\\shadercache\\730)", "Ordner wählen (steamapps\\shadercache\\730)", "Choisir le dossier (steamapps\\shadercache\\730)", "选择文件夹 (steamapps\\shadercache\\730)"],
        ["cs2.detect"] = ["Detect", "Detectar", "Найти", "Erkennen", "Détecter", "检测"],
        ["cs2.mouse.sub"] = ["Imports Windows' default mouse settings, or your own .reg if you chose one in Settings.", "Importa la configuración de ratón predeterminada de Windows, o tu propio .reg si lo has elegido en Ajustes.", "Импортирует стандартные настройки мыши Windows или ваш .reg, если он выбран в настройках.", "Importiert die Windows-Standard-Mauseinstellungen oder deine eigene .reg, falls in den Einstellungen gewählt.", "Importe les réglages de souris par défaut de Windows, ou votre propre .reg si vous l'avez choisi dans Réglages.", "导入 Windows 默认鼠标设置；如果你在设置中选择了自己的 .reg，则导入它。"],
        ["cs2.mouse.btn"] = ["Apply raton.reg", "Aplicar raton.reg", "Применить raton.reg", "raton.reg anwenden", "Appliquer raton.reg", "应用 raton.reg"],
        ["cs2.nv.sub"] = ["Silently imports the RNX Performance profile, optimized for CS2, with NVIDIA Profile Inspector. Both ship inside the program.", "Importa en silencio el perfil RNX Performance, optimizado para CS2, con NVIDIA Profile Inspector. Los dos vienen dentro del programa.", "Тихо импортирует профиль RNX Performance, оптимизированный для CS2, через NVIDIA Profile Inspector. Оба входят в программу.", "Importiert still das für CS2 optimierte Profil RNX Performance mit NVIDIA Profile Inspector. Beides ist im Programm enthalten.", "Importe en silence le profil RNX Performance, optimisé pour CS2, avec NVIDIA Profile Inspector. Les deux sont inclus dans le programme.", "使用 NVIDIA Profile Inspector 静默导入为 CS2 优化的 RNX Performance 配置文件。两者均已内置。"],
        ["cs2.nv.none"] = ["No NVIDIA GPU was detected on this PC: this module only works with NVIDIA cards.", "No se ha detectado una GPU NVIDIA en este equipo: este módulo solo funciona con tarjetas NVIDIA.", "Видеокарта NVIDIA не найдена: модуль работает только с картами NVIDIA.", "Keine NVIDIA-GPU gefunden: Dieses Modul funktioniert nur mit NVIDIA-Karten.", "Aucun GPU NVIDIA détecté : ce module ne fonctionne qu'avec les cartes NVIDIA.", "未检测到 NVIDIA 显卡：此模块仅适用于 NVIDIA 显卡。"],
        ["cs2.nv.open"] = ["Open Inspector", "Abrir Inspector", "Открыть Inspector", "Inspector öffnen", "Ouvrir Inspector", "打开 Inspector"],
        ["cs2.nv.btn"] = ["Import profile", "Importar perfil", "Импорт профиля", "Profil importieren", "Importer le profil", "导入配置文件"],
        ["sc.title"] = ["Desktop shortcuts", "Accesos directos", "Ярлыки на рабочем столе", "Desktop-Verknüpfungen", "Raccourcis sur le bureau", "桌面快捷方式"],
        ["sc.sub"] = ["Runs a mode straight away and closes when it finishes.", "Ejecuta un modo directamente y se cierra al terminar.", "Сразу запускает режим и закрывается по завершении.", "Startet einen Modus direkt und schließt sich danach.", "Lance un mode directement et se ferme à la fin.", "直接运行一个模式，完成后自动关闭。"],
        ["sc.nobackup"] = ["No-backup shortcut", "Acceso sin backup", "Ярлык без копии", "Verknüpfung ohne Sicherung", "Raccourci sans sauvegarde", "“不备份”快捷方式"],
        ["sc.name.nobackup"] = ["RNX - Clean without backup", "RNX - Limpiar sin backup", "RNX - Очистка без копии", "RNX - Ohne Sicherung bereinigen", "RNX - Nettoyer sans sauvegarde", "RNX - 不备份清理"],

        // ---------- Servidores de Valve ----------
        ["nav.servers"] = ["Servers", "Servidores", "Серверы", "Server", "Serveurs", "服务器"],
        ["sv.title"] = ["Valve servers", "Servidores de Valve", "Серверы Valve", "Valve-Server", "Serveurs Valve", "Valve 服务器"],
        ["sv.sub"] = ["Block the locations you don't want to play on. CS2 won't connect to blocked ones in matchmaking. Each block is a Windows Firewall rule; the status is read from the firewall.", "Bloquea las ubicaciones en las que no quieres jugar. CS2 no conectará con las bloqueadas al buscar partida. Cada bloqueo es una regla del Firewall de Windows; el estado se lee del firewall.", "Заблокируйте локации, на которых не хотите играть. CS2 не будет подключаться к ним при поиске матча. Каждая блокировка — правило брандмауэра Windows; состояние читается из брандмауэра.", "Sperre die Standorte, auf denen du nicht spielen willst. CS2 verbindet sich im Matchmaking nicht mit gesperrten. Jede Sperre ist eine Windows-Firewall-Regel; der Status wird aus der Firewall gelesen.", "Bloquez les emplacements où vous ne voulez pas jouer. CS2 ne s'y connectera pas en matchmaking. Chaque blocage est une règle du Pare-feu Windows ; l'état est lu depuis le pare-feu.", "屏蔽你不想玩的服务器位置，匹配时 CS2 不会连接被屏蔽的服务器。每个屏蔽都是一条 Windows 防火墙规则，状态直接从防火墙读取。"],
        ["sv.refresh"] = ["Refresh", "Actualizar", "Обновить", "Aktualisieren", "Actualiser", "刷新"],
        ["sv.unblockAll"] = ["Unblock all", "Desbloquear todo", "Разблокировать все", "Alle entsperren", "Tout débloquer", "全部解除屏蔽"],
