        ["sv.summary"] = ["{0} of {1} blocked", "{0} de {1} bloqueadas", "Заблокировано: {0} из {1}", "{0} von {1} gesperrt", "{0} sur {1} bloqués", "已屏蔽 {0}/{1}"],
        ["sv.cache"] = ["offline: saved list", "sin conexión: lista guardada", "нет сети: сохранённый список", "offline: gespeicherte Liste", "hors ligne : liste enregistrée", "离线：使用已保存的列表"],
        ["sv.loading"] = ["Loading Valve's server list...", "Cargando la lista de servidores de Valve...", "Загрузка списка серверов Valve...", "Serverliste von Valve wird geladen...", "Chargement de la liste des serveurs Valve...", "正在加载 Valve 服务器列表..."],
        ["sv.none"] = ["Couldn't get the server list. Check your connection and press Refresh.", "No se pudo obtener la lista de servidores. Revisa la conexión y pulsa Actualizar.", "Не удалось получить список серверов. Проверьте сеть и нажмите «Обновить».", "Serverliste nicht verfügbar. Prüfe die Verbindung und klicke auf „Aktualisieren“.", "Impossible d'obtenir la liste. Vérifiez la connexion et cliquez sur Actualiser.", "无法获取服务器列表。请检查网络后点击“刷新”。"],
        ["sv.fail"] = ["Couldn't load the servers: {0}", "No se pudieron cargar los servidores: {0}", "Не удалось загрузить серверы: {0}", "Server konnten nicht geladen werden: {0}", "Impossible de charger les serveurs : {0}", "无法加载服务器：{0}"],
        ["sv.dlg.t"] = ["Unblock all locations", "Desbloquear todas las ubicaciones", "Разблокировать все локации", "Alle Standorte entsperren", "Débloquer tous les emplacements", "解除屏蔽所有位置"],
        ["sv.dlg.x"] = ["The {0} firewall rules created by RNX Cache Cleaner are deleted. Other firewall rules aren't touched.", "Se borran las {0} reglas del firewall que creó RNX Cache Cleaner. Las demás reglas no se tocan.", "Будут удалены {0} правил брандмауэра, созданных RNX Cache Cleaner. Остальные правила не затрагиваются.", "Die {0} Firewall-Regeln von RNX Cache Cleaner werden gelöscht. Andere Regeln bleiben unberührt.", "Les {0} règles de pare-feu créées par RNX Cache Cleaner sont supprimées. Les autres règles ne sont pas touchées.", "将删除 RNX Cache Cleaner 创建的 {0} 条防火墙规则，其他规则不受影响。"],
