        ["custom.fixes"] = ["Repairs (by hand only, not in Everything)", "Reparaciones (solo a mano, no van en Todo)", "Исправления (только вручную, не входят в «Всё»)", "Reparaturen (nur manuell, nicht in Alles)", "Réparations (à la main uniquement, pas dans Tout)", "修复（仅手动，不包含在全部模式中）"],
        ["fix.store.title"] = ["Fix Microsoft Store (AtlasOS)", "Arreglar Microsoft Store (AtlasOS)", "Исправить Microsoft Store (AtlasOS)", "Microsoft Store reparieren (AtlasOS)", "Réparer le Microsoft Store (AtlasOS)", "修复 Microsoft Store（AtlasOS）"],
        ["fix.store.sub"] = ["AtlasOS fix for when the Store or apps won't install or update: rebuilds the app deployment database and removes Gaming Services if installed. Restart afterwards.", "Arreglo de AtlasOS para cuando la Store o las apps no instalan ni actualizan: regenera la base de datos de despliegue de apps y quita Gaming Services si está instalado. Reinicia después.", "Исправление AtlasOS, когда Store или приложения не устанавливаются и не обновляются: пересоздаёт базу развёртывания приложений и удаляет Gaming Services, если он установлен. Затем перезагрузите ПК.", "AtlasOS-Fix, wenn Store oder Apps nicht installieren oder aktualisieren: baut die App-Bereitstellungsdatenbank neu auf und entfernt Gaming Services, falls installiert. Danach neu starten.", "Correctif AtlasOS quand le Store ou les applis ne s'installent ou ne se mettent pas à jour : reconstruit la base de déploiement des applis et supprime Gaming Services s'il est installé. Redémarrez ensuite.", "AtlasOS 修复，适用于应用商店或应用无法安装或更新：重建应用部署数据库，并在已安装时移除 Gaming Services。完成后请重启。"],
        ["fix.store.btn"] = ["Run fix", "Ejecutar arreglo", "Запустить исправление", "Reparatur starten", "Lancer le correctif", "运行修复"],
        ["fix.store.notAtlas"] = ["Only for AtlasOS (RunAsTI.cmd not found)", "Solo para AtlasOS (no se encuentra RunAsTI.cmd)", "Только для AtlasOS (RunAsTI.cmd не найден)", "Nur für AtlasOS (RunAsTI.cmd nicht gefunden)", "Uniquement pour AtlasOS (RunAsTI.cmd introuvable)", "仅适用于 AtlasOS（未找到 RunAsTI.cmd）"],
        ["dlg.fix.t"] = ["Run the Microsoft Store fix?", "¿Ejecutar el arreglo de Microsoft Store?", "Запустить исправление Microsoft Store?", "Microsoft-Store-Reparatur starten?", "Lancer le correctif du Microsoft Store ?", "运行 Microsoft Store 修复？"],
        ["dlg.fix.x"] = ["It stops the Store and app services, deletes the app deployment database (StateRepository-Deployment.srd) so Windows rebuilds it, and uninstalls Gaming Services if it's installed. A window shows the progress. Restart the PC when it finishes.", "Para los servicios de la Store y de las apps, borra la base de datos de despliegue de apps (StateRepository-Deployment.srd) para que Windows la regenere y desinstala Gaming Services si está instalado. Una ventana mostrará el progreso. Reinicia el PC al terminar.", "Останавливает службы Store и приложений, удаляет базу развёртывания приложений (StateRepository-Deployment.srd), чтобы Windows её пересоздала, и удаляет Gaming Services, если он установлен. Ход работы покажет отдельное окно. После завершения перезагрузите ПК.", "Stoppt die Store- und App-Dienste, löscht die App-Bereitstellungsdatenbank (StateRepository-Deployment.srd), damit Windows sie neu aufbaut, und deinstalliert Gaming Services, falls installiert. Ein Fenster zeigt den Fortschritt. Danach den PC neu starten.", "Arrête les services du Store et des applis, supprime la base de déploiement des applis (StateRepository-Deployment.srd) pour que Windows la reconstruise et désinstalle Gaming Services s'il est installé. Une fenêtre affiche la progression. Redémarrez le PC à la fin.", "停止应用商店和应用相关服务，删除应用部署数据库（StateRepository-Deployment.srd）以便 Windows 重建，并在已安装时卸载 Gaming Services。进度会在单独窗口中显示。完成后请重启电脑。"],
        ["toast.fix.store"] = ["Store fix running in its own window", "Arreglo de la Store en marcha en su ventana", "Исправление Store выполняется в отдельном окне", "Store-Reparatur läuft in eigenem Fenster", "Correctif du Store en cours dans sa fenêtre", "应用商店修复正在单独窗口中运行"],
        ["lg.fix.store"] = ["STORE FIX: AtlasOS fixStoreIssues.cmd launched", "ARREGLO STORE: lanzado fixStoreIssues.cmd de AtlasOS", "ИСПРАВЛЕНИЕ STORE: запущен fixStoreIssues.cmd от AtlasOS", "STORE-REPARATUR: fixStoreIssues.cmd von AtlasOS gestartet", "CORRECTIF STORE : fixStoreIssues.cmd d'AtlasOS lancé", "应用商店修复：已启动 AtlasOS 的 fixStoreIssues.cmd"],
        ["lg.fix.fail"] = ["STORE FIX: couldn't launch it: {0}", "ARREGLO STORE: no se pudo lanzar: {0}", "ИСПРАВЛЕНИЕ STORE: не удалось запустить: {0}", "STORE-REPARATUR: Start fehlgeschlagen: {0}", "CORRECTIF STORE : lancement impossible : {0}", "应用商店修复：无法启动：{0}"],
        ["dev.title"] = ["Old and faulty devices", "Dispositivos antiguos y con error", "Старые и неисправные устройства", "Alte und fehlerhafte Geräte", "Périphériques anciens et défaillants", "旧设备和故障设备"],
        ["dev.sub"] = ["Removes devices Windows remembers but are no longer connected, and restarts connected ones that report an error. Drivers are kept: if you plug something back in, it reinstalls by itself. Shows the list before doing anything.", "Quita los dispositivos que Windows recuerda pero ya no están conectados y reinicia los conectados que dan error. Los drivers se conservan: si vuelves a conectar algo, se reinstala solo. Enseña la lista antes de hacer nada.", "Удаляет устройства, которые Windows помнит, но которые больше не подключены, и перезапускает подключённые с ошибкой. Драйверы остаются: при повторном подключении устройство установится само. Сначала показывает список.", "Entfernt Geräte, die Windows kennt, die aber nicht mehr verbunden sind, und startet verbundene Geräte mit Fehler neu. Treiber bleiben erhalten: Wird etwas wieder angeschlossen, installiert es sich selbst. Zeigt vorher die Liste.", "Supprime les périphériques que Windows mémorise mais qui ne sont plus connectés et redémarre les périphériques connectés en erreur. Les pilotes sont conservés : si vous rebranchez quelque chose, il se réinstalle seul. Affiche la liste avant d'agir.", "移除 Windows 记住但已不再连接的设备，并重启出错的已连接设备。驱动程序会保留：重新连接设备时会自动重新安装。执行前会先显示列表。"],
        ["dev.btn"] = ["Review…", "Revisar…", "Проверить…", "Prüfen…", "Analyser…", "检查…"],
        ["dev.scanning"] = ["Looking for old and faulty devices…", "Buscando dispositivos antiguos y con error…", "Поиск старых и неисправных устройств…", "Suche nach alten und fehlerhaften Geräten…", "Recherche des périphériques anciens et défaillants…", "正在查找旧设备和故障设备…"],
        ["dev.none"] = ["No old or faulty devices found", "No hay dispositivos antiguos ni con error", "Старых и неисправных устройств нет", "Keine alten oder fehlerhaften Geräte gefunden", "Aucun périphérique ancien ou défaillant", "未发现旧设备或故障设备"],
        ["dev.errorsHeader"] = ["Connected with an error, will be restarted ({0})", "Conectados con error, se reiniciarán ({0})", "Подключены с ошибкой, будут перезапущены ({0})", "Verbunden mit Fehler, werden neu gestartet ({0})", "Connectés en erreur, seront redémarrés ({0})", "已连接但出错，将重启（{0}）"],
        ["dev.dlg.t"] = ["Remove {0} old devices and restart {1} faulty ones?", "¿Quitar {0} dispositivos antiguos y reiniciar {1} con error?", "Удалить старые устройства ({0}) и перезапустить неисправные ({1})?", "{0} alte Geräte entfernen und {1} fehlerhafte neu starten?", "Supprimer {0} périphériques anciens et redémarrer {1} défaillants ?", "移除 {0} 个旧设备并重启 {1} 个故障设备？"],
        ["dev.dlg.x"] = ["Devices that are unplugged right now also count as old: their entry is removed and they reinstall when you plug them in again, but they lose settings saved for that device (audio volume or enhancements, COM port number). A restore point is created first if it's enabled in Settings.", "Los que estén desenchufados ahora también cuentan como antiguos: se borra su entrada y se reinstalan al volver a conectarlos, pero pierden los ajustes guardados de ese dispositivo (volumen o mejoras de audio, número de puerto COM). Antes se crea un punto de restauración si está activado en Ajustes.", "Отключённые сейчас устройства тоже считаются старыми: их запись удаляется, при подключении они переустановятся, но потеряют сохранённые настройки (громкость или эффекты звука, номер COM-порта). Если включено в настройках, сначала создаётся точка восстановления.", "Gerade ausgesteckte Geräte zählen auch als alt: Ihr Eintrag wird entfernt und sie installieren sich beim Wiederanschließen neu, verlieren aber gespeicherte Einstellungen (Audio-Lautstärke oder -Effekte, COM-Port-Nummer). Vorher wird ein Wiederherstellungspunkt erstellt, falls in den Einstellungen aktiviert.", "Les périphériques débranchés en ce moment comptent aussi comme anciens : leur entrée est supprimée et ils se réinstallent quand vous les rebranchez, mais perdent leurs réglages (volume ou effets audio, numéro de port COM). Un point de restauration est créé avant si l'option est activée dans Réglages.", "当前未插入的设备也算作旧设备：其条目会被删除，重新连接时会自动重新安装，但会丢失该设备保存的设置（音量或音效增强、COM 端口号）。如果在设置中启用，会先创建还原点。"],
        ["dev.dlg.yes"] = ["Remove and repair", "Quitar y reparar", "Удалить и исправить", "Entfernen und reparieren", "Supprimer et réparer", "移除并修复"],
        ["dev.toast"] = ["{0} old devices removed, {1} repaired", "{0} dispositivos antiguos quitados, {1} reparados", "Удалено старых устройств: {0}, исправлено: {1}", "{0} alte Geräte entfernt, {1} repariert", "{0} périphériques anciens supprimés, {1} réparés", "已移除 {0} 个旧设备，修复 {1} 个"],
        ["dev.toast.failed"] = ["{0} couldn't be removed", "{0} no se pudieron quitar", "не удалось удалить: {0}", "{0} konnten nicht entfernt werden", "{0} n'ont pas pu être supprimés", "{0} 个无法移除"],
