        ["lg.dev.removeFail"] = ["DEVICES: couldn't remove {0} (code {1})", "DISPOSITIVOS: no se pudo quitar {0} (código {1})", "УСТРОЙСТВА: не удалось удалить {0} (код {1})", "GERÄTE: {0} konnte nicht entfernt werden (Code {1})", "PÉRIPHÉRIQUES : impossible de supprimer {0} (code {1})", "设备：无法移除 {0}（代码 {1}）"],
        ["lg.dev.fixed"] = ["DEVICES: {0} working again", "DISPOSITIVOS: {0} vuelve a funcionar", "УСТРОЙСТВА: {0} снова работает", "GERÄTE: {0} funktioniert wieder", "PÉRIPHÉRIQUES : {0} fonctionne de nouveau", "设备：{0} 已恢复正常"],
        ["lg.dev.stillError"] = ["DEVICES: {0} still reports an error (its driver may need reinstalling)", "DISPOSITIVOS: {0} sigue con error (puede que necesite reinstalar su driver)", "УСТРОЙСТВА: {0} всё ещё с ошибкой (возможно, нужно переустановить драйвер)", "GERÄTE: {0} meldet weiterhin einen Fehler (Treiber evtl. neu installieren)", "PÉRIPHÉRIQUES : {0} est toujours en erreur (son pilote doit peut-être être réinstallé)", "设备：{0} 仍然出错（可能需要重新安装驱动）"],
        ["lg.dev.done"] = ["DEVICES: {0} old removed, {1} failed, {2} repaired", "DISPOSITIVOS: {0} antiguos quitados, {1} fallidos, {2} reparados", "УСТРОЙСТВА: удалено {0}, ошибок {1}, исправлено {2}", "GERÄTE: {0} alte entfernt, {1} fehlgeschlagen, {2} repariert", "PÉRIPHÉRIQUES : {0} anciens supprimés, {1} échecs, {2} réparés", "设备：已移除 {0} 个旧设备，失败 {1} 个，修复 {2} 个"],
        ["lg.dev.fail"] = ["DEVICES: failed: {0}", "DISPOSITIVOS: falló: {0}", "УСТРОЙСТВА: ошибка: {0}", "GERÄTE: fehlgeschlagen: {0}", "PÉRIPHÉRIQUES : échec : {0}", "设备：失败：{0}"],
        // ---------- 5.2.0: color en juegos ----------
        ["vib.state.starting"] = ["On", "Activado", "Включено", "An", "Activé", "已开启"],
        ["bk.cfg.btn"] = ["Restore my RNX settings", "Restaurar mi config de RNX", "Восстановить мои настройки RNX", "Meine RNX-Einstellungen wiederherstellen", "Restaurer mes réglages RNX", "恢复我的 RNX 设置"],
        ["bk.cfg.tip"] = ["Each backup also saves your RNX settings in Drive (language, colors, Custom selection, game colors...). Use this on a new PC after connecting Google.", "Cada backup guarda también tu config de RNX en Drive (idioma, colores, selección de Personalizada, color en juegos...). Úsalo en un PC nuevo después de conectar Google.", "Каждый бэкап также сохраняет настройки RNX на Drive (язык, цвета, выбор «Выборочной», цвет в играх...). Используйте на новом ПК после подключения Google.", "Jedes Backup speichert auch deine RNX-Einstellungen in Drive (Sprache, Farben, Auswahl, Spielfarben...). Nutze das auf einem neuen PC nach dem Verbinden mit Google.", "Chaque sauvegarde enregistre aussi vos réglages RNX dans Drive (langue, couleurs, sélection personnalisée, couleurs en jeu...). Utilisez-le sur un nouveau PC après avoir connecté Google.", "每次备份也会把 RNX 设置保存到 Drive（语言、颜色、自定义选择、游戏色彩……）。在新电脑上连接 Google 后使用。"],
        ["bk.cfg.t"] = ["Restore your RNX settings from Drive?", "¿Restaurar tu config de RNX desde Drive?", "Восстановить настройки RNX с Drive?", "RNX-Einstellungen aus Drive wiederherstellen?", "Restaurer vos réglages RNX depuis Drive ?", "从 Drive 恢复 RNX 设置？"],
        ["bk.cfg.x"] = ["Language, colors, Custom selection, backup options, CS2 font size and game colors (with your games) are replaced by the ones saved in your last backup. Things tied to a PC (paths, power plan, scheduled tasks) are not touched.", "El idioma, los colores, la selección de Personalizada, las opciones de backup, el tamaño de la fuente de CS2 y el color en juegos (con tus juegos) se cambian por los del último backup. Lo que depende del PC (rutas, plan de energía, tareas programadas) no se toca.", "Язык, цвета, выбор «Выборочной», параметры бэкапа, размер шрифта CS2 и цвет в играх (с вашими играми) заменяются сохранёнными в последнем бэкапе. Привязанное к ПК (пути, план питания, задания) не меняется.", "Sprache, Farben, Auswahl, Backup-Optionen, CS2-Schriftgröße und Spielfarben (mit deinen Spielen) werden durch die aus dem letzten Backup ersetzt. PC-gebundene Dinge (Pfade, Energiesparplan, geplante Aufgaben) bleiben unberührt.", "La langue, les couleurs, la sélection personnalisée, les options de sauvegarde, la taille de police de CS2 et les couleurs en jeu (avec vos jeux) sont remplacées par celles de la dernière sauvegarde. Ce qui dépend du PC (chemins, mode d'alimentation, tâches planifiées) n'est pas modifié.", "语言、颜色、自定义选择、备份选项、CS2 字体大小和游戏色彩（含你的游戏）将替换为最近一次备份中的设置。与电脑相关的内容（路径、电源计划、计划任务）不会更改。"],
        ["bk.cfg.login"] = ["Connect Google first", "Primero conecta Google", "Сначала подключите Google", "Verbinde zuerst Google", "Connectez d'abord Google", "请先连接 Google"],
        ["bk.cfg.none"] = ["No RNX settings saved in Drive yet: make a backup first", "Aún no hay config de RNX en Drive: haz antes un backup", "На Drive ещё нет настроек RNX: сначала сделайте бэкап", "Noch keine RNX-Einstellungen in Drive: erst ein Backup machen", "Aucun réglage RNX dans Drive : faites d'abord une sauvegarde", "Drive 中还没有 RNX 设置：请先备份"],
        ["bk.cfg.done"] = ["Your RNX settings are back", "Ya tienes tu config de RNX", "Настройки RNX восстановлены", "Deine RNX-Einstellungen sind zurück", "Vos réglages RNX sont restaurés", "已恢复 RNX 设置"],
        ["lg.dr.settingsUp"] = ["DRIVE: RNX settings saved (rnx_settings.json)", "DRIVE: config de RNX guardada (rnx_settings.json)", "DRIVE: настройки RNX сохранены (rnx_settings.json)", "DRIVE: RNX-Einstellungen gespeichert (rnx_settings.json)", "DRIVE : réglages RNX enregistrés (rnx_settings.json)", "DRIVE：已保存 RNX 设置（rnx_settings.json）"],
        ["lg.dr.settingsFail"] = ["DRIVE: couldn't save the RNX settings: {0}", "DRIVE: no se pudo guardar la config de RNX: {0}", "DRIVE: не удалось сохранить настройки RNX: {0}", "DRIVE: RNX-Einstellungen konnten nicht gespeichert werden: {0}", "DRIVE : impossible d'enregistrer les réglages RNX : {0}", "DRIVE：无法保存 RNX 设置：{0}"],
        ["lg.cfg.restored"] = ["SETTINGS: RNX settings restored from Drive", "AJUSTES: config de RNX restaurada desde Drive", "НАСТРОЙКИ: настройки RNX восстановлены с Drive", "EINSTELLUNGEN: RNX-Einstellungen aus Drive wiederhergestellt", "RÉGLAGES : réglages RNX restaurés depuis Drive", "设置：已从 Drive 恢复 RNX 设置"],
        ["lg.cfg.fail"] = ["SETTINGS: restore failed: {0}", "AJUSTES: falló la restauración: {0}", "НАСТРОЙКИ: ошибка восстановления: {0}", "EINSTELLUNGEN: Wiederherstellung fehlgeschlagen: {0}", "RÉGLAGES : échec de la restauration : {0}", "设置：恢复失败：{0}"],
        ["nav.vibrance"] = ["Game colors", "Color en juegos", "Цвет в играх", "Spielfarben", "Couleurs en jeu", "游戏色彩"],
        ["vib.title"] = ["Game colors (digital vibrance)", "Color en juegos (digital vibrance)", "Цвет в играх (digital vibrance)", "Spielfarben (Digital Vibrance)", "Couleurs en jeu (vibrance numérique)", "游戏色彩（数字振动）"],
        ["vib.sub"] = ["Like vibranceGUI: when a game from the list is in front, its colors get more saturated (and its resolution can change). When you leave it, Windows goes back to normal. RNX stays in the tray next to the clock while this is on.", "Como vibranceGUI: cuando un juego de la lista está delante, sus colores se saturan más (y puede cambiar su resolución). Al salir, Windows vuelve a la normalidad. Mientras esté activado, RNX se queda en la bandeja junto al reloj.", "Как vibranceGUI: когда игра из списка на переднем плане, цвета становятся насыщеннее (и может меняться разрешение). При выходе Windows возвращается к обычному виду. Пока функция включена, RNX остаётся в трее у часов.", "Wie vibranceGUI: Ist ein Spiel aus der Liste im Vordergrund, werden die Farben gesättigter (und die Auflösung kann wechseln). Verlässt du es, kehrt Windows zum Normalzustand zurück. Solange aktiv, bleibt RNX im Infobereich neben der Uhr.", "Comme vibranceGUI : quand un jeu de la liste est au premier plan, ses couleurs sont plus saturées (et sa résolution peut changer). En le quittant, Windows revient à la normale. Tant que c'est activé, RNX reste dans la zone de notification près de l'horloge.", "与 vibranceGUI 相同：列表中的游戏处于前台时，色彩会更鲜艳（还可以切换分辨率）。离开游戏后 Windows 恢复正常。启用期间，RNX 会留在时钟旁的托盘中。"],
        ["vib.nogpu"] = ["Needs an NVIDIA or AMD graphics card.", "Necesita una gráfica NVIDIA o AMD.", "Нужна видеокарта NVIDIA или AMD.", "Benötigt eine NVIDIA- oder AMD-Grafikkarte.", "Nécessite une carte graphique NVIDIA ou AMD.", "需要 NVIDIA 或 AMD 显卡。"],
        ["vib.state.off"] = ["Off", "Desactivado", "Выключено", "Aus", "Désactivé", "已关闭"],
        ["vib.state.on"] = ["On: waiting for a game from the list", "Activado: esperando a un juego de la lista", "Включено: ожидание игры из списка", "An: wartet auf ein Spiel aus der Liste", "Activé : en attente d'un jeu de la liste", "已开启：等待列表中的游戏"],
        ["vib.state.game"] = ["On: {0} in front", "Activado: {0} delante", "Включено: {0} на переднем плане", "An: {0} im Vordergrund", "Activé : {0} au premier plan", "已开启：{0} 在前台"],
        ["vib.state.error"] = ["Couldn't start, see the log", "No se pudo iniciar, mira el registro", "Не удалось запустить, см. журнал", "Start fehlgeschlagen, siehe Protokoll", "Démarrage impossible, voir le journal", "无法启动，请查看日志"],
        ["vib.gpu"] = ["Graphics card: {0}", "Gráfica: {0}", "Видеокарта: {0}", "Grafikkarte: {0}", "Carte graphique : {0}", "显卡：{0}"],
        ["vib.other"] = ["vibranceGUI is open too. Two programs changing the colors at the same time fight each other: close it (you can import its games first).", "vibranceGUI también está abierto. Dos programas cambiando los colores a la vez se pisan: ciérralo (antes puedes importar sus juegos).", "vibranceGUI тоже открыт. Две программы, меняющие цвета одновременно, мешают друг другу: закройте её (сначала можно импортировать игры).", "vibranceGUI ist auch geöffnet. Zwei Programme, die gleichzeitig die Farben ändern, stören sich: Schließe es (vorher kannst du seine Spiele importieren).", "vibranceGUI est aussi ouvert. Deux programmes qui changent les couleurs en même temps se gênent : fermez-le (vous pouvez d'abord importer ses jeux).", "vibranceGUI 也在运行。两个程序同时更改色彩会互相冲突：请关闭它（可先导入它的游戏）。"],
        ["vib.other.btn"] = ["Close vibranceGUI", "Cerrar vibranceGUI", "Закрыть vibranceGUI", "vibranceGUI schließen", "Fermer vibranceGUI", "关闭 vibranceGUI"],
        ["vib.default"] = ["Windows color", "Color de Windows", "Цвет Windows", "Windows-Farbe", "Couleur de Windows", "Windows 色彩"],
        ["vib.default.h"] = ["Level outside the games. 50 % (NVIDIA) or 100 % (AMD) is normal.", "Nivel fuera de los juegos. Lo normal es 50 % (NVIDIA) o 100 % (AMD).", "Уровень вне игр. Обычно 50 % (NVIDIA) или 100 % (AMD).", "Wert außerhalb der Spiele. Normal ist 50 % (NVIDIA) bzw. 100 % (AMD).", "Niveau hors des jeux. La normale est 50 % (NVIDIA) ou 100 % (AMD).", "游戏外的色彩级别。正常为 50%（NVIDIA）或 100%（AMD）。"],
        ["vib.primary"] = ["Main monitor only", "Solo el monitor principal", "Только основной монитор", "Nur Hauptmonitor", "Écran principal uniquement", "仅主显示器"],
        ["vib.primary.h"] = ["Off: the color changes on all your monitors.", "Apagado: el color cambia en todos tus monitores.", "Выкл.: цвет меняется на всех мониторах.", "Aus: Die Farbe ändert sich auf allen Monitoren.", "Désactivé : la couleur change sur tous vos écrans.", "关闭时：所有显示器的色彩都会改变。"],
